"use client"

import { ChartLines, type LineChartProps } from "@/components/ui/line-chart"

type AreaChartProps = LineChartProps

/**
 * Volume as a barcode: no fill, only hairlines dropped from the line to the baseline at a close,
 * even rhythm. Several series stack, each band its own rhythm, and the readout sums them.
 */
function AreaChart(props: AreaChartProps) {
  return <ChartLines {...props} area />
}

export { AreaChart, type AreaChartProps }

@layer components {
  /* ── db-area-chart ── volume as a barcode: no fill, only hairlines dropped from the line to the
     baseline at a close even rhythm, SPECTRA's barcode laid under a line. Stacked series each keep
     their own rhythm, three, six and twelve pixels apart, so the bands read by density, not colour. */
  .db-area-chart-drops { stroke: none; }
  .db-area-chart .db-line-chart-draw pattern > rect { fill: var(--db-rule-strong); }
  .db-area-chart .db-line-chart-draw > [data-series="0"] pattern > rect { fill: var(--db-pencil); }
  .db-area-chart.db-chart .db-line-chart-draw > [data-series] > .db-line-chart-line { stroke: var(--db-ink); stroke-dasharray: none; }
  .db-area-chart.db-chart .db-chart-swatch { --c: var(--db-pencil); block-size: 0.8em; background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 3px); }
  .db-area-chart.db-chart .db-chart-row[data-series="1"] .db-chart-swatch { background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 6px); }
  .db-area-chart.db-chart .db-chart-row[data-series="2"] .db-chart-swatch { background: repeating-linear-gradient(to right, var(--c) 0 1px, transparent 1px 12px); }

  @media (forced-colors: active) {
    .db-area-chart .db-line-chart-draw pattern > rect { fill: GrayText; }
  }
}
